```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, k, u;
    if (scanf("%d %d %d", &n, &k, &u) != 3) return 0;

    int *cards = malloc((size_t)n * k * sizeof(int));
    int *position = malloc((size_t)(u + 1) * sizeof(int));

    for (int i = 0; i < n * k; i++) {
        scanf("%d", &cards[i]);
    }

    for (int i = 1; i <= u; i++) {
        int number;
        scanf("%d", &number);
        position[number] = i;
    }

    int *completion = malloc((size_t)n * sizeof(int));
    int earliest = u + 1;

    for (int i = 0; i < n; i++) {
        int last = 0;
        for (int j = 0; j < k; j++) {
            int draw_position = position[cards[i * k + j]];
            if (draw_position > last) last = draw_position;
        }
        completion[i] = last;
        if (last < earliest) earliest = last;
    }

    int first = 1;
    for (int i = 0; i < n; i++) {
        if (completion[i] == earliest) {
            if (!first) printf(" ");
            printf("%d", i + 1);
            first = 0;
        }
    }
    printf("\n");

    free(cards);
    free(position);
    free(completion);
    return 0;
}
```

